select
id, cell_sha256_code_list, package_id
from b_xiecheng_cps_colliding_data_loop_cycle
where is_delete = 0 and retry_count = 0
 and release_time < #{endDate}

    and id > #{minId}

order by id limit #{pageSize};

select id, cell_sha256_code_list, package_id, retry_count, push_time from b_xiecheng_cps_colliding_data_loop_cycle where is_delete = 0 and retry_count > 0 and retry_count <= 3
and id > #{minId}
order by id asc limit #{pageSize};

mapper.update:
update b_xiecheng_cps_colliding_data_loop_cycle
set push_time = #{pushTime},
    update_time = #{updateTime},
    retry_count = #{retryCount},
    release_time = #{releaseTime}
where id = #{id}
